const DEFAULT_ITERS: u64 = 32;

#[derive(Parser)]
#[command(about = "Qwen3-4B model-level operator report")]
struct Cli {
    /// Only `decode` is implemented in the MVP.
    command: String,
    #[arg(long = "batch-size")]
    batch_size: usize,
    #[arg(long = "kv-len")]
    kv_len: usize,
    #[arg(long, default_value = "text")]
