    let qkv = HiddenStates::zeros(&ctx, q_dim + 2 * kv_dim, batch)?;
    let mut q = HiddenStates::zeros(&ctx, q_dim, batch)?;
    let mut k = HiddenStates::zeros(&ctx, kv_dim, batch)?;
    let mut v = HiddenStates::zeros(&ctx, kv_dim, batch)?;
