use std::collections::BTreeMap;
use std::collections::HashMap;
use std::fmt::Write as _;
use std::fs;
use std::io;
use std::path::PathBuf;

use anyhow::Result;
use anyhow::Context;
use clap::Parser;
use pegainfer_bench::Accum;
use pegainfer_bench::LatencyStats;
use pegainfer_bench::MeasuredCall;
use pegainfer_bench::accumulate;
use pegainfer_bench::attr_usize;
use pegainfer_bench::axis;
use pegainfer_bench::bench_key;
use pegainfer_bench::call_site_row;
use pegainfer_bench::input;
use pegainfer_bench::measure_loop;
use pegainfer_bench::output;
use pegainfer_bench::rollup_row;
use pegainfer_kernels::tensor::AttentionLayout;
use pegainfer_kernels::tensor::DataType;
use pegainfer_kernels::tensor::DeviceContext;
use pegainfer_kernels::tensor::GpuWeight;
use pegainfer_kernels::tensor::KernelCall;
use pegainfer_kernels::tensor::TensorSpec;
use pegainfer_kernels::tensor::layout_2d;
use pegainfer_kernels::tensor::zeros_1d;
use pegainfer_kernels::tensor::zeros_3d;
use serde::Serialize;
use serde_json;

fn main() -> Result<()> {
    let args = Args::parse();
    let ctx = DeviceContext::init()?;
    let attention = AttentionLayout::default();
    let calls = qwen3::schedule_for_report(&args.model, &args.sequence_length, &attention)?;
    let mut per_call = BTreeMap::new();
    for call in calls {
        let label = bench_key(&call)?;
        if !per_call.contains_key(&label) {
            let measured = measure_call(&ctx, &call);
            per_call.insert(label, measured);
        }
    }
    let total = per_call
        .values()
        .filter_map(|m| m.stats.as_ref())
        .map(|s| s.mean_us)
        .sum::<f64>();
    let report = Report {
        schedule_sha: qwen3::report_sha(),
        model: args.model,
        sequence_length: args.sequence_length,
        total_mean_us: total,
        per_call,
    };
    let path = PathBuf::from(&args.out);
    if let Some(dir) = path.parent() {
        fs::create_dir_all(dir)?;
    }
    let json = serde_json::to_string_pretty(&report)?;
    fs::write(&path, json)?;
    println!("Wrote {}", path.display());
    Ok(())
}

fn measure_call(ctx: &DeviceContext, call: &KernelCall) -> MeasuredCall {
    match call.op.as_str() {
        "gemm" => measure_gemm(ctx, call),
        "attention" => measure_attention(ctx, call),
        "rms_norm" => measure_rms_norm(ctx, call),
        "rope" => measure_rope(ctx, call),
        "all_reduce" => {
            let stats = LatencyStats::zero(call.iters);
            MeasuredCall { supported: true, reason: None, stats: Some(stats) }
        }
        op => {
            let reason = format!("op `{op}` is not measured yet");
            MeasuredCall { supported: false, reason: Some(reason), stats: None }
        }
    }
}

fn measure_gemm(ctx: &DeviceContext, call: &KernelCall) -> MeasuredCall {
    let m = match axis(call.inputs.first().expect("gemm input matrix"), "rows") {
        Ok(v) => v,
        Err(err) => return unsupported("gemm missing input rows", err),
    };
    let n = match axis(call.outputs.first().expect("gemm output matrix"), "cols") {
        Ok(v) => v,
        Err(err) => return unsupported("gemm missing output cols", err),
    };
    let k = match attr_usize(call, "k") {
        Ok(v) => v,
        Err(err) => return unsupported("gemm missing k", err),
    };
    let a = zeros_2d::<f32>(ctx, m, k);
    let b = zeros_2d::<f32>(ctx, k, n);
    let c = zeros_2d::<f32>(ctx, m, n);
    match measure_loop(ctx, call.iters, || {
        gemm(ctx, &a, &b, &c);
        Ok(())
    }) {
        Ok(stats) => MeasuredCall { supported: true, reason: None, stats: Some(stats) },
        Err(err) => return unsupported("gemm measure failed", err),
    }
}
