pub fn from_samples(iters: u64, mut samples: Vec<f64>) -> Result<LatencyStats> {
    if samples.is_empty() {
        bail!("latency sample set is empty");
    }
    samples.sort_by(f64::total_cmp);
    let mean_us = samples.iter().sum::<f64>() / samples.len() as f64;
    let stddev_us = if samples.len() > 1 {
        let variance = samples
            .iter()
            .map(|sample| {
                let delta = sample - mean_us;
                delta * delta
            })
            .sum::<f64>()
            / (samples.len() - 1) as f64;
        variance.sqrt()
    } else {
        0.0
    };
    Ok(Self {
        iters,
        mean_us,
        stddev_us,
        min_us: samples[0],
        p50_us: percentile(&samples, 0.50),
        p95_us: percentile(&samples, 0.95),
        p99_us: percentile(&samples, 0.99),
        max_us: samples[samples.len() - 1],
    })
}
```

