// 示例代码：独立小工具 bench_stats_drill.rs（不属于 pegainfer 仓库）
// 复刻 pegainfer-bench 中 LatencyStats::from_samples / percentile 的统计算法，
// 用 100 次“模拟迭代”的耗时样本来观察各统计量对尖刺的敏感度。
// 运行：rustc --edition 2021 -O bench_stats_drill.rs && ./bench_stats_drill
fn percentile(sorted: &[f64], quantile: f64) -> f64 {
    let idx = ((sorted.len() as f64 - 1.0) * quantile).ceil() as usize;
    sorted[idx.min(sorted.len() - 1)]
}

fn stats(mut samples: Vec<f64>) {
    samples.sort_by(f64::total_cmp);
    let n = samples.len() as f64;
    let mean = samples.iter().sum::<f64>() / n;
    let variance = samples
        .iter()
        .map(|s| {
            let d = s - mean;
            d * d
        })
        .sum::<f64>()
        / (samples.len() - 1) as f64;
    println!(
        "iters={} mean={:.1} stddev={:.1} min={:.1} p50={:.1} p95={:.1} p99={:.1} max={:.1}",
        samples.len(),
        mean,
        variance.sqrt(),
        samples[0],
        percentile(&samples, 0.50),
        percentile(&samples, 0.95),
        percentile(&samples, 0.99),
        samples[samples.len() - 1],
    );
}

fn main() {
    // 100 次模拟迭代：97 次稳定在 1000µs，3 次（第 7、42、91 次）尖刺到 5000µs。
    let samples: Vec<f64> = (0..100)
        .map(|i| if matches!(i, 7 | 42 | 91) { 5000.0 } else { 1000.0 })
        .collect();
    stats(samples);
